#if defined(__AVX2__)
#include <immintrin.h>

/* AVX2-optimized 3-channel LUT processing - processes 8 pixels at a time */
static void
process_row_3ch_avx2(UINT32 *rowOut, const UINT8 *rowIn, int xsize,
                     UINT32 scale1D, UINT32 scale2D, UINT32 scale3D,
                     int stride1D, int stride2D, int stride3D,
                     const INT16 *table) {
    int x;
    __m256i scale1D_vec = _mm256_set1_epi32(scale1D);
    __m256i scale2D_vec = _mm256_set1_epi32(scale2D);
    __m256i scale3D_vec = _mm256_set1_epi32(scale3D);
    __m256i scale_mask_vec = _mm256_set1_epi32(SCALE_MASK);
    int shift_diff = SCALE_BITS - SHIFT_BITS;

    for (x = 0; x < xsize - 7; x += 8) {
        /* Load 8 pixels (32 bytes = 8 * 4 bytes per pixel) */
        __m256i pixels = _mm256_loadu_si256((const __m256i*)(rowIn + x * 4));

        /* Extract R, G, B channels */
        __m256i r8 = _mm256_and_si256(pixels, _mm256_set1_epi32(0xFF));
        __m256i g8 = _mm256_and_si256(_mm256_srli_epi32(pixels, 8), _mm256_set1_epi32(0xFF));
        __m256i b8 = _mm256_and_si256(_mm256_srli_epi32(pixels, 16), _mm256_set1_epi32(0xFF));
        __m256i a8 = _mm256_and_si256(_mm256_srli_epi32(pixels, 24), _mm256_set1_epi32(0xFF));

        /* Compute indices */
        __m256i index1D = _mm256_mullo_epi32(r8, scale1D_vec);
        __m256i index2D = _mm256_mullo_epi32(g8, scale2D_vec);
        __m256i index3D = _mm256_mullo_epi32(b8, scale3D_vec);

        /* Compute shifts */
        __m256i shift1D = _mm256_srli_epi32(_mm256_and_si256(index1D, scale_mask_vec), shift_diff);
        __m256i shift2D = _mm256_srli_epi32(_mm256_and_si256(index2D, scale_mask_vec), shift_diff);
        __m256i shift3D = _mm256_srli_epi32(_mm256_and_si256(index3D, scale_mask_vec), shift_diff);

        /* Compute base indices (table position) */
        __m256i idx1D = _mm256_srli_epi32(index1D, SCALE_BITS);
        __m256i idx2D = _mm256_srli_epi32(index2D, SCALE_BITS);
        __m256i idx3D = _mm256_srli_epi32(index3D, SCALE_BITS);

        /* base_idx = idx1D * stride1D + idx2D * stride2D + idx3D * stride3D */
        __m256i stride1D_vec = _mm256_set1_epi32(stride1D);
        __m256i stride2D_vec = _mm256_set1_epi32(stride2D);
        __m256i stride3D_vec = _mm256_set1_epi32(stride3D);

        __m256i base_idx = _mm256_add_epi32(
            _mm256_add_epi32(
                _mm256_mullo_epi32(idx1D, stride1D_vec),
                _mm256_mullo_epi32(idx2D, stride2D_vec)),
            _mm256_mullo_epi32(idx3D, stride3D_vec));

        /* For each of 8 pixels, we need to do trilinear interpolation.
           Since each pixel has different base_idx, we process them individually
           but use SIMD for the interpolation math. */

        /* Extract individual indices and process */
        int32_t base_indices[8];
        int16_t shifts1D[8], shifts2D[8], shifts3D[8];
        _mm256_storeu_si256((__m256i*)base_indices, base_idx);
        _mm256_storeu_si256((__m256i*)shifts1D, shift1D);
        _mm256_storeu_si256((__m256i*)shifts2D, shift2D);
        _mm256_storeu_si256((__m256i*)shifts3D, shift3D);

        for (int i = 0; i < 8; i++) {
            const INT16 *t = table + base_indices[i];
            INT16 shift1 = shifts1D[i] & 0xFFFF;
            INT16 shift2 = shifts2D[i] & 0xFFFF;
            INT16 shift3 = shifts3D[i] & 0xFFFF;

            INT16 leftleft[4], leftright[4], left[4];
            INT16 rightleft[4], rightright[4], right[4];
            INT16 result[4];

            /* Interpolate along 1D (r) axis */
            interpolate3(leftleft, t, t + stride1D, shift1);
            interpolate3(leftright, t + stride2D, t + stride2D + stride1D, shift1);
            interpolate3(left, leftleft, leftright, shift2);

            interpolate3(rightleft, t + stride3D, t + stride3D + stride1D, shift1);
            interpolate3(rightright, t + stride3D + stride2D, t + stride3D + stride2D + stride1D, shift1);
            interpolate3(right, rightleft, rightright, shift2);

            interpolate3(result, left, right, shift3);

            rowOut[x + i] = MAKE_UINT32(
                clip8(result[0]),
                clip8(result[1]),
                clip8(result[2]),
                _mm256_extract_epi32(a8, i));
        }
    }

    /* Handle remaining pixels */
    for (; x < xsize; x++) {
        UINT32 index1D = rowIn[x * 4 + 0] * scale1D;
        UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
        UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
        INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
        INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
        INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);

        int base_idx = (index1D >> SCALE_BITS) * stride1D +
                       (index2D >> SCALE_BITS) * stride2D +
                       (index3D >> SCALE_BITS) * stride3D;

        INT16 result[4], left[4], right[4];
        INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];
        const INT16 *t = table + base_idx;

        interpolate3(leftleft, t, t + stride1D, shift1D);
        interpolate3(leftright, t + stride2D, t + stride2D + stride1D, shift1D);
        interpolate3(left, leftleft, leftright, shift2D);

        interpolate3(rightleft, t + stride3D, t + stride3D + stride1D, shift1D);
        interpolate3(rightright, t + stride3D + stride2D, t + stride3D + stride2D + stride1D, shift1D);
        interpolate3(right, rightleft, rightright, shift2D);

        interpolate3(result, left, right, shift3D);

        rowOut[x] = MAKE_UINT32(
            clip8(result[0]),
            clip8(result[1]),
            clip8(result[2]),
            rowIn[x * 4 + 3]);
    }
}

